import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"節","description":"東坡易傳 - 節","frontmatter":{"title":"節","description":"東坡易傳 - 節"},"headers":[],"relativePath":"classics/dongpo/061.md","filePath":"classics/dongpo/061.md"}'),o={name:"classics/dongpo/061.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="節" tabindex="-1">節 <a class="header-anchor" href="#節" aria-label="Permalink to “節”">​</a></h1><p>“節”，亨。苦節，不可貞。</p><p>《彖》曰：“節，亨”，剛柔分而剛得中。 “苦節，不可貞”，其道窮也【謂六三也】。說以行險，當位以節，中正以通【謂九二也】。</p><p>“剛柔分”者，“兌”下而“坎”上也；“剛得中”者，謂二、五也。此所以為“節，亨”也。 “兌”施“節”於“坎”，故曰“說以行險”。天地節而四時成。節以制度，不傷財，不害民。</p><p>象曰：澤上有水，“節”；君子以制數度、議德行。</p><p>“數度”者，其政事也；“德行”者，其教化也；皆所以為民物之“節”也。</p><p>初九：不出戶庭，無咎。象曰：“不出戶庭”，知通塞也。</p><p>九二：不出門庭，兇。象曰：“不出門庭，兇”；失時極也。</p><p>“節”者，事之會也。君子見吉凶之幾，發而中其會，謂之“節”。《詩?東方未明》，刺無節也。其詩曰：“不能晨夜，不夙則莫。”言無節者不識事之會，或失則早，或失則莫也。“澤上有水，節”，以澤節水者也。虛則納之，滿則流之，其權在澤。初九、九二、六三，“澤”也，節人者也；六四、九五、上六，水也；節於人者也。節之於初九則太早，節之於六三則太莫，故九二者，施節之時、當發之會也。水之始至，澤當塞而不當通；既至，當通而不當塞。故初九以“不出戶庭”為“無咎”，言當塞也；九二以“不出門庭”為“兇”，言當通也。至是而不通，則失時而至於極，六三是也，是禍福之交、成敗之決也。故孔子曰：“君不密，則失臣；臣不密，則失身。幾事不密，則害成。”</p><p>六三：不節若，則嗟若，無咎。象曰：“不節”之“嗟”，又誰咎也？</p><p>諮嗟而節之，以為不可不節也。九二之節，節於未滿。節之者樂見，節者甘焉。六三之節，節於既溢；節之者嗟，見節者苦焉。若節者人之所不能堪，而人終莫之咎者，知六三之不得巳也。嗟者，不得已之見於外者也。</p><p>六四：安節，亨。象曰：“安節”之“亨”，承上道也。</p><p>六四承節於九五，在其上不在其身，故六四安焉。</p><p>九五：甘節，吉；往有尚。象曰：“甘節”之“吉”，居位中也。</p><p>畜而至於極，然後節之，其節也必爭。九二施節於不爭之中，此九五之所樂也，故曰“甘節”。樂則流，甘則壞；故以往適上六，陰陽相配、甘苦相濟為吉也。</p><p>上六：苦節，貞兇；悔亡。象曰：“苦節貞兇”，其道窮也。</p><p>《易》有“兇”而“無咎”者，“大過”之上六、“困”之九二是也；則未有“兇”而能“悔亡”者。亦如人之未有既死而病癒者也。上六“貞兇、悔亡”者，何也？“兇”者六三，“悔亡”者上六也。是以知“節”者在“坎”，而見“節”者之在“兌”也。六三施苦節於我，出於不得已則“無咎”，以是為正則兇矣，而我“悔亡”。</p>',17)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
